","known_bad_label":"Returns aliases to the selected input objects and their nested labels arrays instead of independent copies."},{"id":"cap-v2-ordering_and_selection-typescript-generation-02","problem":"Implement a complete TypeScript source file exporting exactly the following declarations:

```ts
export interface SnapshotTrack {
  trackId: string;
  title: string;
  revision: number;
  fidelity: number;
  contributors: string[];
}

export interface MergedTrack {
  trackId: string;
  title: string;
  revision: number;
  fidelity: number;
  contributors: string[];
}

export function mergeTrackSnapshots(
  left: SnapshotTrack[],
  right: SnapshotTrack[],
): MergedTrack[];
```

All fields satisfy their declared types and all numeric fields are finite. A track ID may occur multiple times in either snapshot.

Select exactly one record for each distinct `trackId`. Prefer higher `revision`, then higher `fidelity`, then a record from `left`, and finally the earlier position within its source array. Order the selected tracks by lexicographically smaller `title`, then lexicographically smaller `trackId`, using UTF-16 code-unit order.

Within each returned track, sort `contributors` lexicographically using the same ordering. Neither input array, any input record, nor any input `contributors` array may be mutated. Returned records and contributor arrays must not alias input records or arrays.

Use only standard language and runtime APIs. Do not access the filesystem, network, clock, or randomness.","reference_code":"export interface SnapshotTrack {
  trackId: string;
  title: string;
  revision: number;
  fidelity: number;
  contributors: string[];
}

export interface MergedTrack {
  trackId: string;
  title: string;
  revision: number;
  fidelity: number;
  contributors: string[];
}

interface Candidate {
  track: SnapshotTrack;
  sourceRank: number;
  position: number;
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareCandidates(left: Candidate, right: Candidate): number {
  if (left.track.revision !== right.track.revision) {
    return right.track.revision - left.track.revision;
  }
  if (left.track.fidelity !== right.track.fidelity) {
    return right.track.fidelity - left.track.fidelity;
  }
  if (left.sourceRank !== right.sourceRank) {
    return left.sourceRank - right.sourceRank;
  }
  return left.position - right.position;
}

export function mergeTrackSnapshots(
  left: SnapshotTrack[],
  right: SnapshotTrack[],
): MergedTrack[] {
  const winners = new Map<string, Candidate>();
  const sources: Array<{ tracks: SnapshotTrack[]; sourceRank: number }> = [
    { tracks: left, sourceRank: 0 },
    { tracks: right, sourceRank: 1 },
  ];

  for (const source of sources) {
    source.tracks.forEach((track, position) => {
      const candidate: Candidate = { track, sourceRank: source.sourceRank, position };
      const current = winners.get(track.trackId);
      if (current === undefined || compareCandidates(candidate, current) < 0) {
        winners.set(track.trackId, candidate);
      }
    });
  }

  const result = Array.from(winners.values(), ({ track }) => ({
    trackId: track.trackId,
    title: track.title,
    revision: track.revision,
    fidelity: track.fidelity,
    contributors: [...track.contributors].sort(compareText),
  }));

  result.sort((leftTrack, rightTrack) => {
    const byTitle = compareText(leftTrack.title, rightTrack.title);
    return byTitle !== 0 ? byTitle : compareText(leftTrack.trackId, rightTrack.trackId);
  });

  return result;
}
