st COMPONENT_PATTERN = /^(?:[A-Za-z0-9_.!~*'()-]|%[0-9A-Fa-f]{2})*$/;\\n\\nfunction compareText(left: string, right: string): number {\\n  return left < right ? -1 : left > right ? 1 : 0;\\n}\\n\\nfunction decodeComponent(component: string): string {\\n  if (!COMPONENT_PATTERN.test(component)) {\\n    throw new Error(\\\"Invalid encoded pairs\\\");\\n  }\\n  try {\\n    return decodeURIComponent(component);\\n  } catch {\\n    throw new Error(\\\"Invalid encoded pairs\\\");\\n  }\\n}\\n\\nexport function canonicalizeEncodedPairs(text: string): string {\\n  if (text === \\\"\\\") {\\n    return \\\"\\\";\\n  }\\n\\n  const pairs: ParsedPair[] = text.split(\\\"&\\\").map((segment, index) => {\\n    const separator = segment.indexOf(\\\"=\\\");\\n    if (separator < 0 || separator !== segment.lastIndexOf(\\\"=\\\")) {\\n      throw new Error(\\\"Invalid encoded pairs\\\");\\n    }\\n\\n    const key = decodeComponent(segment.slice(0, separator));\\n    const value = decodeComponent(segment.slice(separator + 1));\\n    if (key.length === 0) {\\n      throw new Error(\\\"Invalid encoded pairs\\\");\\n    }\\n    return { key, value, index };\\n  });\\n\\n  pairs.sort((left, right) => {\\n    const byKey = compareText(left.key, right.key);\\n    if (byKey !== 0) {\\n      return byKey;\\n    }\\n    const byValue = compareText(left.value, right.value);\\n    return byValue !== 0 ? byValue : left.index - right.index;\\n  });\\n\\n  return pairs\\n    .map(({ key, value }) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)\\n    .join(\\\"&\\\");\\n}\\n\",\"known_bad_code\":\"interface ParsedPair {\\n  key: string;\\n  value: string;\\n  index: number;\\n}\\n\\nconst COMPONENT_PATTERN = /^(?:[A-Za-z0-9_.!~*'()-]|%[0-9A-Fa-f]{2})*$/;\\n\\nfunction compareText(left: string, right: string): number {\\n  return left < right ? -1 : left > right ? 1 : 0;\\n}\\n\\nfunction decodeComponent(component: string): string {\\n  if (!COMPONENT_PATTERN.test(component)) {\\n    throw new Error(\\\"Invalid encoded pairs\\\");\\n  }\\n  try {\\n    return decodeURIComponent(component);\\n  } catch {\\n    throw new Error(\\\"Invalid encoded pairs\\\");\\n  }\\n}\\n\\nexport function canonicalizeEncodedPairs(text: string): string {\\n  if (text === \\\"\\\") {\\n    return \\\"\\\";\\n  }\\n\\n  const pairs: ParsedPair[] = text.split(\\\"&\\\").map((segment, index) => {\\n    const separator = segment.indexOf(\\\"=\\\");\\n    if (separator < 0 || separator !== segment.lastIndexOf(\\\"=\\\")) {\\n      throw new Error(\\\"Invalid encoded pairs\\\");\\n    }\\n\\n    const key = decodeComponent(segment.slice(0, separator));\\n    const value = decodeComponent(segment.slice(separator + 1));\\n    if (key.length === 0) {\\n      throw new Error(\\\"Invalid encoded pairs\\\");\\n    }\\n    return { key, value, index };\\n  });\\n\\n  pairs.sort((left, right) => {\\n    const byKey = compareText(left.key, right.key);\\n    return byKey !== 0 ? byKey : left.index - right.index;\\n  });\\n\\n  return pairs\\n    .map(({ key, value }) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)\\n    .join(\\\"&\\\");\\n}\\n\",\"known_bad_label\":\"Orders equal-key pairs by input position without applying the required decoded-value tie-breaker.\"}]}"}}
