{"items":[{"id":"cap-v2-ordering_and_selection-typescript-generation-01","test_code":"import { selectReviewCandidates, type ReviewCandidate } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function assertJsonEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, got ${actualJson}`);
  }
}

const candidates: ReviewCandidate[] = [
  { id: 'low', priority: -1, quality: 100, arrival: 0, labels: ['low'] },
  { id: 'a', priority: 1, quality: 5, arrival: 0, labels: ['lowercase'] },
  { id: '\uE000', priority: 1, quality: 5, arrival: 0, labels: ['private'] },
  { id: 'quality', priority: 1, quality: 9, arrival: 100, labels: ['q'] },
  { id: 'early', priority: 1, quality: 5, arrival: -1, labels: ['early', 'second'] },
  { id: 'A', priority: 1, quality: 5, arrival: 0, labels: ['uppercase'] },
  { id: '😀', priority: 1, quality: 5, arrival: 0, labels: ['emoji'] },
  { id: 'priority', priority: 2, quality: -100, arrival: 999, labels: [] },
];
const originalJson = JSON.stringify(candidates);
const originalObjects = candidates.slice();
const originalLabels = candidates.map((candidate) => candidate.labels);

const selected = selectReviewCandidates(candidates, candidates.length);
assertJsonEqual(
  selected.map((candidate) => candidate.id),
  ['priority', 'quality', 'early', 'A', 'a', '😀', '\uE000', 'low'],
  'candidates must be ranked by all specified keys using UTF-16 ordering',
);
assertEqual(JSON.stringify(candidates), originalJson, 'the input must not be mutated');

for (const result of selected) {
  const inputIndex = candidates.findIndex((candidate) => candidate.id === result.id);
  assert(inputIndex >= 0, 'every result must correspond to an input');
  assert(result !== originalObjects[inputIndex], `result object ${result.id} must be newly allocated`);
  assert(result.labels !== originalLabels[inputIndex], `labels for ${result.id} must be newly allocated`);
}

selected[0].priority = 999;
selected[0].labels.push('changed');
assertEqual(candidates[7].priority, 2, 'mutating a returned object must not affect input');
assertJsonEqual(candidates[7].labels, [], 'mutating returned labels must not affect input labels');

const firstThree = selectReviewCandidates(candidates, 3);
assertJsonEqual(firstThree.map((candidate) => candidate.id), ['priority', 'quality', 'early'], 'limit must truncate ranked results');
assert(firstThree[0] !== candidates[7], 'objects in a truncated result must also be cloned');
assert(firstThree[0].labels !== candidates[7].labels, 'labels in a truncated result must also be cloned');

assertJsonEqual(selectReviewCandidates(candidates, 0), [], 'zero limit must return an empty array');
assertJsonEqual(selectReviewCandidates([], 0), [], 'empty input must return an empty array');
assertEqual(JSON.stringify(candidates), originalJson, 'all calls must leave the input unchanged');"},{"id":"cap-v2-ordering_and_selection-typescript-generation-02","test_code":"import { mergeTrackSnapshots, type SnapshotTrack } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function assertJsonEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson = JSON.stringify(actual);
  const expectedJson = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message}: expected ${expectedJson}, got ${actualJson}`);
  }
}

const left: SnapshotTrack[] = [
  { trackId: 'dup', title: 'Zulu', revision: 2, fidelity: 5, contributors: ['zoe', 'Amy', 'amy'] },
  { trackId: 'dup', title: 'LaterLeft', revision: 2, fidelity: 5, contributors: ['wrong'] },
  { trackId: 'rightWinsRevision', title: 'LoseRevision', revision: 1, fidelity: 99, contributors: ['left'] },
  { trackId: 'early', title: 'First', revision: 1, fidelity: 1, contributors: ['b', 'a'] },
  { trackId: 'early', title: 'Second', revision: 1, fidelity: 1, contributors: ['later'] },
  { trackId: 'fidelity', title: 'LoseFidelity', revision: 3, fidelity: 1, contributors: ['left'] },
];
const right: SnapshotTrack[] = [
  { trackId: 'dup', title: 'RightTie', revision: 2, fidelity: 5, contributors: ['right'] },
  { trackId: 'rightWinsRevision', title: 'Alpha', revision: 2, fidelity: 0, contributors: ['z', 'A'] },
  { trackId: 'fidelity', title: 'Gamma', revision: 3, fidelity: 2, contributors: ['two', 'one'] },
  { trackId: 'rightOnly', title: 'Beta', revision: 4, fidelity: 4, contributors: [] },
  { trackId: 'rightOnly', title: 'LaterRight', revision: 4, fidelity: 4, contributors: ['wrong'] },
];

const leftBefore = JSON.stringify(left);
const rightBefore = JSON.stringify(right);
const allInputRecords = [...left, ...right];
const allContributorArrays = allInputRecords.map((track) => track.contributors);

const merged = mergeTrackSnapshots(left, right);
assertJsonEqual(
  merged,
  [
    { trackId: 'rightWinsRevision', title: 'Alpha', revision: 2, fidelity: 0, contributors: ['A', 'z'] },
    { trackId: 'rightOnly', title: 'Beta', revision: 4, fidelity: 4, contributors: [] },
    { trackId: 'early', title: 'First', revision: 1, fidelity: 1, contributors: ['a', 'b'] },
    { trackId: 'fidelity', title: 'Gamma', revision: 3, fidelity: 2, contributors: ['one', 'two'] },
    { trackId: 'dup', title: 'Zulu', revision: 2, fidelity: 5, contributors: ['Amy', 'amy', 'zoe'] },
  ],
  'merge must select and order tracks and sort contributors correctly',
