function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function assertThrowsInvalid(action: () => unknown, message: string): void {
  let thrown: unknown = undefined;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  if (!(thrown instanceof Error) || thrown.message !== 'Invalid encoded pairs') {
    throw new Error(`${message}: expected Error(\"Invalid encoded pairs\")`);
  }
}

assertEqual(canonicalizeEncodedPairs(''), '', 'empty input represents zero segments');
assertEqual(canonicalizeEncodedPairs('a=1'), 'a=1', 'a simple pair must be preserved');
assertEqual(
  canonicalizeEncodedPairs('b=2&a=3&a=1'),
  'a=1&a=3&b=2',
  'pairs must be sorted by decoded key and then decoded value',
);
assertEqual(
  canonicalizeEncodedPairs('%7a=%2f&%41=%7e&plain=%41%42%43'),
  'A=~&plain=ABC&z=%2F',
  'unnecessary escapes and hexadecimal case must be normalized',
);
assertEqual(
  canonicalizeEncodedPairs("symbols=!~*'()&empty="),
  "empty=&symbols=!~*'()",
  'all encodeURIComponent-safe punctuation and empty values must be accepted',
);
assertEqual(
  canonicalizeEncodedPairs('%EE%80%80=x&%F0%9F%98%80=x&Z=x&a=x'),
  'Z=x&a=x&%F0%9F%98%80=x&%EE%80%80=x',
  'decoded strings must be sorted by UTF-16 code-unit order',
);
assertEqual(
  canonicalizeEncodedPairs('same=%41&same=A&%73ame=A'),
  'same=A&same=A&same=A',
  'equal decoded pairs must all be retained and canonicalized',
);
assertEqual(
  canonicalizeEncodedPairs('%E2%82%AC=%F0%9F%98%80'),
  '%E2%82%AC=%F0%9F%98%80',
  'valid multi-byte UTF-8 escapes must decode and re-encode',
);

const invalidInputs = [
  'a',
  'a=b=c',
  '=value',
  '&',
  'a=1&',
  '&a=1',
  'a=1&&b=2',
  '%=value',
  '%0=value',
  '%GG=value',
  '%C3%28=value',
  '%ED%A0%80=value',
  'a=%F0%28%8C%28',
  'raw space=value',
  'a=raw space',
  'a=/slash',
  'a=comma,value',
  'é=value',
  'a=😀',
];
for (const input of invalidInputs) {
  assertThrowsInvalid(() => canonicalizeEncodedPairs(input), `malformed input ${JSON.stringify(input)} must be rejected`);
}"}]}

