      if (left.job.urgency !== right.job.urgency) {
        return right.job.urgency - left.job.urgency;
      }
      if (left.job.duration !== right.job.duration) {
        return left.job.duration - right.job.duration;
      }
      const byId = compareText(left.job.jobId, right.job.jobId);
      return byId !== 0 ? byId : left.index - right.index;
    })
    .slice(0, capacity)
    .map(({ job }) => ({ ...job }));
}
