Export exactly this API:

```typescript
export function canonicalizeProperties(source: string): string;
```

The input is a text document containing zero or more lines separated by `\n` or `\r\n`. Empty lines are ignored. Every nonempty line must have the form `key=value`, where:

- `key` matches `[A-Za-z][A-Za-z0-9_-]*`.
- Keys are case-sensitive and may occur only once.
- `value` is an ASCII URI-component representation. Decode it with URI percent-decoding; malformed percent escapes or invalid UTF-8 must cause an `Error`.

Return a canonical document in which each decoded value is URI-component encoded again, percent escapes use uppercase hexadecimal, and the lines are ordered by ascending key using ordinary string comparison. Join lines with `\n` and do not add a trailing newline. Characters `!`, `'`, `(`, `)`, and `*` must be percent-encoded even though `encodeURIComponent` normally leaves them unchanged.

Throw an `Error` for a malformed line, invalid key, duplicate key, non-ASCII encoded value, or decoding failure. The implementation must be deterministic and use no filesystem, network, clock, randomness, external package, or framework.","reference_code":"function encodeCanonicalComponent(value: string): string {
    return encodeURIComponent(value)
        .replace(/[!'()*]/g, character =>
            `%${character.charCodeAt(0).toString(16).toUpperCase()}`,
        )
        .replace(/%[0-9a-f]{2}/gi, escape => escape.toUpperCase());
}

export function canonicalizeProperties(source: string): string {
    const properties = new Map<string, string>();

    for (const line of source.split(/\r?\n/)) {
        if (line === "") {
            continue;
        }

        const separator = line.indexOf("=");
        if (separator < 0) {
            throw new Error("Malformed property line");
        }

        const key = line.slice(0, separator);
        const encodedValue = line.slice(separator + 1);

        if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(key)) {
            throw new Error("Invalid property key");
        }
        if (properties.has(key)) {
            throw new Error("Duplicate property key");
        }
        if (!/^[\x20-\x7E]*$/.test(encodedValue)) {
            throw new Error("Encoded value must be ASCII");
        }

        let value: string;
        try {
            value = decodeURIComponent(encodedValue);
        } catch {
            throw new Error("Invalid URI-component value");
        }
        properties.set(key, value);
    }

    return [...properties.entries()]
        .sort(([leftKey], [rightKey]) =>
            leftKey < rightKey ? -1 : leftKey > rightKey ? 1 : 0,
        )
        .map(([key, value]) => `${key}=${encodeCanonicalComponent(value)}`)
        .join("\n");
}
