{"items":[{"id":"cap-v2-parsing_and_encoding-typescript-generation-02","test_code":"import { canonicalizeProperties } from './solution';

function assertEqual(actual: unknown, expected: unknown, message: string): void {
    if (actual !== expected) {
        throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
    }
}

function assertThrows(action: () => unknown, message: string): void {
    let threw = false;
    try {
        action();
    } catch (error) {
        if (!(error instanceof Error)) {
            throw new Error(`${message}: threw a non-Error value`);
        }
        threw = true;
    }
    if (!threw) {
        throw new Error(`${message}: expected an Error`);
    }
}

assertEqual(canonicalizeProperties(''), '', 'empty document');
assertEqual(canonicalizeProperties('\n\r\n\n'), '', 'empty lines are ignored');
assertEqual(
    canonicalizeProperties('z=last\r\nAlpha=hello%20world\r\na=%7e'),
    'Alpha=hello%20world\na=~\nz=last',
    'keys are sorted and values are canonically encoded',
);
assertEqual(
    canonicalizeProperties("symbols=!%27()*"),
    'symbols=%21%27%28%29%2A',
    'special encodeURIComponent exceptions are percent-encoded',
);
assertEqual(
    canonicalizeProperties('unicode=%E2%98%83%20caf%C3%A9'),
    'unicode=%E2%98%83%20caf%C3%A9',
    'valid UTF-8 is decoded and re-encoded',
);
assertEqual(
    canonicalizeProperties('safe=AZaz09-_.%7E'),
    'safe=AZaz09-_.~',
    'unreserved characters use canonical literal form',
);
assertEqual(
    canonicalizeProperties('empty='),
    'empty=',
    'empty values are accepted',
);
assertEqual(
    canonicalizeProperties('b=2\na=1\n'),
    'a=1\nb=2',
    'a trailing empty line is ignored without adding output newline',
);
assertEqual(
    canonicalizeProperties('a-b=1\na_b=2\na0=3'),
    'a-b=1\na0=3\na_b=2',
    'valid boundary key characters sort by ordinary string comparison',
);

assertThrows(() => canonicalizeProperties('missingSeparator'), 'line without equals');
assertThrows(() => canonicalizeProperties('=value'), 'empty key');
assertThrows(() => canonicalizeProperties('1key=value'), 'key starting with digit');
assertThrows(() => canonicalizeProperties('bad.key=value'), 'invalid key character');
assertThrows(() => canonicalizeProperties('key=value\nkey=other'), 'duplicate key');
assertThrows(() => canonicalizeProperties('Key=one\nKey=two'), 'case-sensitive exact duplicate');
assertEqual(canonicalizeProperties('Key=one\nkey=two'), 'Key=one\nkey=two', 'differently cased keys are distinct');
assertThrows(() => canonicalizeProperties('key=café'), 'non-ASCII encoded value');
assertThrows(() => canonicalizeProperties('key=%'), 'incomplete percent escape');
assertThrows(() => canonicalizeProperties('key=%G0'), 'non-hex percent escape');
assertThrows(() => canonicalizeProperties('key=%C3%28'), 'invalid UTF-8');
assertThrows(() => canonicalizeProperties('key=%ED%A0%80'), 'UTF-8 encoded surrogate');

const stableSource = 'b=%2a\na=%7e';
assertEqual(canonicalizeProperties(stableSource), 'a=~\nb=%2A', 'first deterministic call');
assertEqual(canonicalizeProperties(stableSource), 'a=~\nb=%2A', 'repeated deterministic call');"},{"id":"cap-v2-parsing_and_encoding-typescript-repair-01","test_code":"import { IdentifierListParser } from './solution';

function assertArrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
    if (actual.length !== expected.length) {
        throw new Error(`${message}: expected length ${expected.length}, got ${actual.length}`);
    }
    for (let index = 0; index < expected.length; index += 1) {
        if (actual[index] !== expected[index]) {
            throw new Error(`${message}: mismatch at index ${index}`);
        }
    }
}

function assertThrows(action: () => unknown, message: string): void {
    let threw = false;
    try {
        action();
    } catch (error) {
        if (!(error instanceof Error)) {
            throw new Error(`${message}: threw a non-Error value`);
        }
        threw = true;
    }
    if (!threw) {
        throw new Error(`${message}: expected an Error`);
    }
}

const parser = new IdentifierListParser();
assertArrayEqual(parser.parse(''), [], 'empty source produces empty list');
assertArrayEqual(
    parser.parse(' Alpha, beta-2 ,GAMMA '),
    ['alpha', 'beta-2', 'gamma'],
    'tokens are trimmed, lowercased, validated, and ordered',
);
assertArrayEqual(parser.parse('z'), ['z'], 'single-character identifier');
assertArrayEqual(parser.parse('A0-b9'), ['a0-b9'], 'digits and hyphens after first character');

assertArrayEqual(parser.parse('first,second'), ['first', 'second'], 'first isolation call');
assertArrayEqual(parser.parse('third'), ['third'], 'later call excludes earlier identifiers');
assertArrayEqual(parser.parse(''), [], 'empty call remains isolated after nonempty calls');

const returned = parser.parse('mutable,result');
returned.push('injected');
returned[0] = 'changed';
assertArrayEqual(parser.parse('fresh'), ['fresh'], 'mutating a returned array does not affect later calls');

assertThrows(() => parser.parse(' '), 'whitespace-only token is empty');
assertThrows(() => parser.parse(',alpha'), 'leading empty token');
assertThrows(() => parser.parse('alpha,'), 'trailing empty token');
assertThrows(() => parser.parse('alpha,,beta'), 'interior empty token');
assertThrows(() => parser.parse('2alpha'), 'identifier cannot start with digit');
assertThrows(() => parser.parse('-alpha'), 'identifier cannot start with hyphen');
assertThrows(() => parser.parse('alpha_beta'), 'underscore is invalid');
assertThrows(() => parser.parse('alpha beta'), 'embedded space is invalid');
assertThrows(() => parser.parse('valid,invalid!'), 'invalid token makes the call fail');
assertArrayEqual(parser.parse('after-error'), ['after-error'], 'failed call does not contaminate a later call');"},{"id":"cap-v2-parsing_and_encoding-typescript-repair-02","test_code":"import { SymbolDocumentDecoder } from './solution';

