assertThrows(() => decoder.decode('@later\nlater=value'), 'forward reference');
assertThrows(() => decoder.decode('name=one\nname=two'), 'duplicate definition');
assertThrows(() => decoder.decode('Name=one\nName=two'), 'exact case-sensitive duplicate');
assertArrayEqual(
    decoder.decode('Name=upper\nname=lower\n@Name\n@name'),
    ['upper', 'lower'],
    'differently cased names are distinct',
);
assertThrows(() => decoder.decode('invalid-name=value'), 'hyphen is invalid in a name');
assertThrows(() => decoder.decode('1name=value'), 'name cannot start with digit');
assertThrows(() => decoder.decode('=value'), 'empty definition name');
assertThrows(() => decoder.decode('bareLine'), 'definition without equals');
assertThrows(() => decoder.decode('@'), 'empty reference name');
