export class IdentifierListParser {
    private readonly parsed: string[] = [];

    parse(source: string): string[] {
        if (source === "") {
            return [...this.parsed];
        }

        for (const rawToken of source.split(",")) {
            const identifier = rawToken.trim().toLowerCase();
            if (!/^[a-z][a-z0-9-]*$/.test(identifier)) {
                throw new Error("Invalid identifier");
            }
            this.parsed.push(identifier);
        }

        return [...this.parsed];
